    state.filterPolicies[29]='block';
    storageSet('lfv3_pro_profile_rules',JSON.stringify([...base,...extra]));savePrefs();storageRemove(decisionCacheKey());state.generationSignature='';state.decisionRankingCache=null;renderProProfilePanel();setDecisionSearchPanel({status:'warn',tested:0,approvedCount:0,eligibleCount:0,resultText:'Perfil PRO alterado. Inicie nova busca exaustiva.',mode:proProfileSummary()});toast('Perfil PRO atualizado. F29 permanece sempre bloqueado.');
