    if(!oneWinnerProfilePromise)oneWinnerProfilePromise=fetch('/api/one-winner-profile'+(force?'?refresh='+Date.now():''),{cache:'no-store'}).then(async r=>{const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||('HTTP '+r.status));oneWinnerProfileCache=d;return d;}).finally(()=>{oneWinnerProfilePromise=null;});
