  function renderEmojiLocks(set=new Set(state.decision)){const el=$('#emoji-locks');el.innerHTML=markerData().map(x=>{const count=[...set].filter(n=>x.set.has(n)).length,locked=state.emojiLocks.has(x.key);return `<button class="emoji-lock ${locked?'active':''}" data-emoji-lock="${x.key}" title="${locked?'Desbloquear':'Bloquear'} ${x.label}">${x.emoji} ${x.label} <b>${count}/15</b><i>${locked?'BLOQUEADO':'permitido'}</i></button>`;}).join('');$$('[data-emoji-lock]').forEach(b=>b.onclick=()=>{const k=b.dataset.emojiLock;state.emojiLocks.has(k)?state.emojiLocks.delete(k):state.emojiLocks.add(k);savePrefs();const blocked=blockedNumbers();state.selection=new Set([...state.selection].filter(n=>!blocked.has(n)));generateDecision();renderExclusions();});}
