  function verticalPctBand(pct){if(pct>=99.5)return{cls:'p100',label:'100%',color:'#1e3a8a'};if(pct>=89.5)return{cls:'p90',label:'90%',color:'#00e5ff'};if(pct>=79.5)return{cls:'p80',label:'80%',color:'#166534'};if(pct>=69.5)return{cls:'p70',label:'70%',color:'#39ff14'};if(pct>=59.5)return{cls:'p60',label:'60%',color:'#f97316'};if(pct>=49.5)return{cls:'p50',label:'50%',color:'#facc15'};if(pct>=39.5)return{cls:'p40',label:'40%',color:'#b91c1c'};if(pct>=29.5)return{cls:'p30',label:'30%',color:'#9ca3af'};return{cls:'p0',label:'10/20%',color:'#050505'};}
